import { useRangePair } from './useRangePair';
import './styles.css';

export type Range = { start: number; end: number };
export type Props = {
  min: number;
  max: number;
  onApply: (range: Range) => void;
};

export function Component({ min, max, onApply }: Props) {
  const model = useRangePair(min, max, onApply);

  return (
    <form
      aria-label="Range pair"
      data-testid="panel"
      className="range-panel"
      onSubmit={model.submit}
    >
      <label>
        Start
        <select
          value={model.start}
          aria-invalid={model.error.startInvalid}
          onChange={(event) => model.setStart(event.currentTarget.value)}
        >
          <option value="">Choose</option>
          {model.options.map((value) => (
            <option key={value} value={String(value)}>{value}</option>
          ))}
        </select>
      </label>
      <label>
        End
        <select
          value={model.end}
          aria-invalid={model.error.endInvalid}
          onChange={(event) => model.setEnd(event.currentTarget.value)}
        >
          <option value="">Choose</option>
          {model.options.map((value) => (
            <option key={value} value={String(value)}>{value}</option>
          ))}
        </select>
      </label>
      <button type="submit">Apply</button>
      {model.error.message && <p role="alert">{model.error.message}</p>}
    </form>
  );
}

